registerSubsystem("Platform", {});
registerSubsystem("Jobs", {"Platform"});
registerSubsystem("Assets", {"Platform", "Jobs"});
registerSubsystem("Renderer", {"Platform", "Assets"});
registerSubsystem("Gameplay", {"Assets", "Renderer"});

auto order = topologicalSort(subsystems);
for (auto* system : order) system->start();
for (auto* system : reverse(order)) system->stop();

while (running) {
    pumpPlatformMessages();
    accumulator += min(clock.tick(), maxFrameDelta);

    while (accumulator >= fixedStep) {
        sampleInput();
        simulate(fixedStep);
        accumulator -= fixedStep;
    }

    const float alpha = accumulator / fixedStep;
    buildRenderState(alpha);
    render();
    present();
}
